<template>
  <q-page class="payments-page">
    <main class="payments-shell">
      <h1 class="sr-only">Payments</h1>
      <section v-if="loading" class="surface loading-panel" aria-busy="true"><div v-for="index in 4" :key="index" class="skeleton" /><span class="sr-only">Loading payments</span></section>
      <section v-else-if="error" class="surface state-panel state-panel--error" role="alert"><span class="state-icon"><IconifyIcon icon="lucide:cloud-alert" width="24" aria-hidden="true" /></span><h2>Unable to load payments</h2><p>{{ error }}</p><button type="button" class="primary-action" @click="loadPayments"><IconifyIcon icon="lucide:refresh-cw" width="17" aria-hidden="true" /> Retry</button></section>
      <template v-else-if="lease">
        <section v-if="actionablePayments.length" class="payment-section" aria-labelledby="action-heading"><div class="section-heading"><div><h2 id="action-heading">Payment required</h2><p>Submit proof for a due payment.</p></div><span>{{ actionablePayments.length }}</span></div><article v-for="payment in actionablePayments" :key="payment.id" class="surface action-card" :class="{ 'action-card--overdue': payment.status === 'overdue' }"><span class="action-icon"><IconifyIcon :icon="payment.status === 'overdue' ? 'lucide:circle-alert' : 'lucide:receipt-text'" width="21" aria-hidden="true" /></span><div><strong>{{ formatPeso(payment.amount) }}</strong><span>{{ formatMonth(payment.month) }}</span><small>{{ payment.status === 'overdue' ? 'This payment is overdue.' : 'Payment is due.' }}</small></div><button type="button" @click="openPaymentMethod(payment)">Pay now</button></article></section>
        <section v-if="pendingPayments.length" class="payment-section" aria-labelledby="pending-heading"><div class="section-heading"><div><h2 id="pending-heading">Awaiting verification</h2><p>Your landlord will review the submitted proof.</p></div><span>{{ pendingPayments.length }}</span></div><div class="surface payment-list"><article v-for="payment in pendingPayments" :key="payment.id" class="payment-row"><span class="payment-icon payment-icon--warning"><IconifyIcon icon="lucide:clock-3" width="19" aria-hidden="true" /></span><div class="payment-copy"><strong>{{ formatPeso(payment.amount) }}</strong><span>{{ formatMonth(payment.month) }}</span><small>{{ methodLabel(payment.method) }}<template v-if="payment.txnReference"> · {{ payment.txnReference }}</template></small></div><span class="status-badge status-badge--warning">Pending review</span></article></div></section>
        <section v-if="lease && !actionablePayments.length && !advancing" class="payment-section" aria-labelledby="advance-heading">
          <div class="section-heading"><div><h2 id="advance-heading">All settled</h2><p>You can pay next month’s rent in advance.</p></div></div>
          <div class="surface action-card action-card--advance"><span class="action-icon"><IconifyIcon icon="lucide:calendar-plus" width="21" aria-hidden="true" /></span><div><strong>Pay in advance</strong><span>Cover {{ advanceMonthLabel }} early and stay worry-free.</span></div><button type="button" @click="payNextMonth">Pay now</button></div>
        </section>
        <section class="payment-section" aria-labelledby="history-heading"><div class="section-heading"><div><h2 id="history-heading">Payment history</h2><p>Confirmed and previous lease payments.</p></div><span>{{ historyPayments.length }}</span></div><div v-if="historyPayments.length" class="surface payment-list"><article v-for="payment in historyPayments" :key="payment.id" class="payment-row"><span class="payment-icon" :class="payment.status === 'paid' ? 'payment-icon--success' : payment.status === 'overdue' ? 'payment-icon--danger' : 'payment-icon--neutral'"><IconifyIcon :icon="payment.status === 'paid' ? 'lucide:circle-check' : 'lucide:receipt-text'" width="19" aria-hidden="true" /></span><div class="payment-copy"><strong>{{ formatPeso(payment.amount) }}</strong><span>{{ formatMonth(payment.month) }}</span><small>{{ payment.status === 'paid' && payment.paidAt ? `Confirmed ${formatDate(payment.paidAt)}` : statusLabel(payment.status) }}</small></div><div class="history-side"><span class="status-badge" :class="`status-badge--${toneForStatus(payment.status)}`">{{ statusLabel(payment.status) }}</span><a v-if="payment.proofUrl" :href="payment.proofUrl" target="_blank" rel="noopener">View proof</a></div></article></div><div v-else class="surface empty-history"><IconifyIcon icon="lucide:receipt-text" width="22" aria-hidden="true" /><p>No payments recorded for this lease.</p></div></section>
        <section class="surface lease-details" aria-labelledby="lease-heading"><h2 id="lease-heading">Lease terms</h2><div><span>Monthly rent</span><strong>{{ formatPeso(lease.monthlyRent || 0) }}</strong></div><div><span>Advance paid</span><strong>{{ formatPeso(lease.advancePaid || 0) }}</strong></div><div><span>Deposit paid</span><strong>{{ formatPeso(lease.depositPaid || 0) }}</strong></div><div><span>Lease period</span><strong>{{ formatDate(lease.startDate) }} – {{ formatDate(lease.endDate) }}</strong></div></section>
      </template>
      <section v-else class="surface state-panel"><span class="state-icon"><IconifyIcon icon="lucide:house" width="24" aria-hidden="true" /></span><h2>No active lease</h2><p>Payment records will appear here once you have an active accommodation lease.</p></section>
    </main>
    <q-dialog v-model="methodDialog" position="bottom"><q-card class="sheet-card"><q-card-section class="sheet-heading"><div><h2>Select payment method</h2><p v-if="selectedPayment">{{ formatPeso(selectedPayment.amount) }} for {{ formatMonth(selectedPayment.month) }}</p></div><q-btn flat round dense icon="close" aria-label="Close payment method" @click="methodDialog = false" /></q-card-section><q-card-section><q-list separator><q-item v-for="method in paymentMethods" :key="method.value" tag="label" clickable><q-item-section avatar><q-radio v-model="selectedMethod" :val="method.value" color="teal-8" /></q-item-section><q-item-section><q-item-label>{{ method.label }}</q-item-label><q-item-label caption>{{ method.hint }}</q-item-label></q-item-section></q-item></q-list></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" @click="methodDialog = false" /><q-btn no-caps unelevated class="primary-action" :disable="!selectedMethod" label="Continue" @click="continuePayment" /></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="proofDialog" position="bottom"><q-card class="sheet-card"><q-card-section class="sheet-heading"><div><h2>Submit payment proof</h2><p>Attach your transaction screenshot or receipt.</p></div><q-btn flat round dense icon="close" aria-label="Close proof upload" @click="proofDialog = false" /></q-card-section><q-card-section><AuthFileDropZone v-model="proofFile" label="Attach proof of payment" accept=".jpg,.jpeg,.png,.pdf,image/*" /><p v-if="proofFile" class="selected-file">{{ proofFile.name }}</p><p class="file-hint">JPG, PNG, or PDF · maximum 5 MB</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" @click="proofDialog = false" /><q-btn no-caps unelevated class="primary-action" :loading="submitting" :disable="!proofFile" label="Submit payment" @click="submitPayment" /></q-card-actions></q-card></q-dialog>
  </q-page>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Icon as IconifyIcon } from '@iconify/vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import { supabase } from '@/shared/utils/supabase'
import { createNotification } from '@/boot/notify'
import { formatPeso } from '@/shared/utils/format'
import { uploadDocument } from '@/shared/utils/upload'
import AuthFileDropZone from '@/modules/auth/components/AuthFileDropZone.vue'
interface Lease { id: string; startDate: string | null; endDate: string | null; monthlyRent: number | null; advancePaid: number | null; depositPaid: number | null }
interface Payment { id: string; month: string; amount: number; status: string; method: string; txnReference: string | null; proofUrl: string | null; paidAt: string | null }
const $q = useQuasar(); const router = useRouter(); const loading = ref(true); const error = ref<string | null>(null); const lease = ref<Lease | null>(null);
const leaseManagerId = ref<string | null>(null); const payments = ref<Payment[]>([]); const methodDialog = ref(false); const proofDialog = ref(false); const selectedPayment = ref<Payment | null>(null); const selectedMethod = ref<string | null>(null); const proofFile = ref<File | null>(null); const submitting = ref(false)
const paymentMethods = [{ value: 'gcash', label: 'GCash', hint: 'Transfer through the GCash app' }, { value: 'maya', label: 'Maya', hint: 'Transfer through the Maya app' }, { value: 'bank', label: 'Bank transfer', hint: 'Direct bank transfer or InstaPay' }, { value: 'cash', label: 'Cash', hint: 'Use the agreed in-person payment method' }]
const actionablePayments = computed(() => payments.value.filter((payment) => ['due', 'overdue'].includes(payment.status))); const pendingPayments = computed(() => payments.value.filter((payment) => payment.status === 'pending_verification')); const historyPayments = computed(() => payments.value.filter((payment) => !['due', 'overdue', 'pending_verification'].includes(payment.status)))
function formatDate(value: string | null) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Date unavailable' : date.toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) }; function formatMonth(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Payment month unavailable' : date.toLocaleDateString('en-PH', { month: 'long', year: 'numeric' }) }; function methodLabel(method: string) { return (method || 'Method not recorded').replace(/_/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()) }; function statusLabel(status: string) { return status === 'paid' ? 'Paid' : status === 'overdue' ? 'Overdue' : status === 'due' ? 'Due' : status === 'pending_verification' ? 'Pending review' : status || 'Unknown' }; function toneForStatus(status: string) { return status === 'paid' ? 'success' : status === 'overdue' ? 'danger' : status === 'due' || status === 'pending_verification' ? 'warning' : 'neutral' }
async function loadPayments() { loading.value = true; error.value = null; try { const { data: { user }, error: authError } = await supabase.auth.getUser(); if (authError) throw authError; if (!user) { void router.push('/login'); return }; const { data: leaseRow, error: leaseError } = await (supabase as any).from('leases').select('id, start_date, end_date, monthly_rent, advance_paid, deposit_paid, accommodation_manager_id').eq('student_id', user.id).in('status', ['active', 'leave_requested']).maybeSingle(); if (leaseError) throw leaseError; if (!leaseRow) { lease.value = null; payments.value = []; return }; lease.value = { id: leaseRow.id, startDate: leaseRow.start_date, endDate: leaseRow.end_date, monthlyRent: leaseRow.monthly_rent, advancePaid: leaseRow.advance_paid, depositPaid: leaseRow.deposit_paid };
leaseManagerId.value = leaseRow.accommodation_manager_id ?? null; const { data: paymentRows, error: paymentError } = await (supabase as any).from('payments').select('id, month, amount, status, method, txn_reference, proof_url, paid_at').eq('lease_id', leaseRow.id).order('month', { ascending: false }); if (paymentError) throw paymentError; payments.value = (paymentRows ?? []).map((payment: any) => ({ id: payment.id, month: payment.month || '', amount: Number(payment.amount || 0), status: payment.status || '', method: payment.method || '', txnReference: payment.txn_reference, proofUrl: payment.proof_url, paidAt: payment.paid_at })) } catch (reason) { error.value = reason instanceof Error ? reason.message : 'We could not retrieve your payments.' } finally { loading.value = false } }
function openPaymentMethod(payment: Payment) { selectedPayment.value = payment; selectedMethod.value = null; proofFile.value = null; methodDialog.value = true }; function continuePayment() { if (!selectedMethod.value) return; methodDialog.value = false; proofDialog.value = true }
const advancing = ref(false)
const advanceMonthLabel = ref('next month')

async function payNextMonth() {
  if (!lease.value || advancing.value) return
  advancing.value = true
  try {
    const now = new Date()
    const next = new Date(now.getFullYear(), now.getMonth() + 1, 1)
    // payments.month is a DATE column — 'YYYY-MM-01', not 'YYYY-MM' (400 otherwise).
    const monthKey = `${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, '0')}`
    const month = `${monthKey}-01`
    advanceMonthLabel.value = next.toLocaleDateString('en-PH', { month: 'long', year: 'numeric' })
    const amount = Number(lease.value.monthlyRent || 0) || 0
    if (!amount) throw new Error('Monthly rent is not set on this lease.')

    const { data: existing } = await (supabase as any).from('payments').select('id').eq('lease_id', lease.value.id).eq('month', month).maybeSingle()
    if (!existing) {
      const { error } = await (supabase as any).from('payments').insert({
        lease_id: lease.value.id,
        amount,
        month,
        method: 'cash',
        status: 'due',
      })
      if (error) throw error
    }
    await loadPayments()
    const duePayment = payments.value.find((p) => p.month.startsWith(monthKey) && ['due', 'overdue'].includes(p.status))
    if (duePayment) openPaymentMethod(duePayment)
  } catch (reason) {
    $q.notify({ type: 'negative', message: reason instanceof Error ? reason.message : 'Could not start advance payment', position: 'top' })
  } finally {
    advancing.value = false
  }
}

async function submitPayment() { if (!selectedPayment.value || !selectedMethod.value || !proofFile.value) return; submitting.value = true; try { const { data: { user } } = await supabase.auth.getUser(); if (!user) throw new Error('Please sign in again.'); const proofUrl = await uploadDocument(proofFile.value, user.id, 'payment_proof'); const transactionReference = `TXN-${Date.now().toString().slice(-8)}`; const { error: updateError } = await (supabase as any).from('payments').update({ method: selectedMethod.value, proof_url: proofUrl, txn_reference: transactionReference, status: 'pending_verification' }).eq('id', selectedPayment.value.id); if (updateError) throw updateError;
    if (leaseManagerId.value) {
      try {
        await createNotification(leaseManagerId.value, 'Payment proof submitted', `${formatPeso(selectedPayment.value.amount)} for ${formatMonth(selectedPayment.value.month)} — verify it in Tenants.`, 'payment', '/landlord/tenants');
      } catch { /* non-critical */ }
    }
    proofDialog.value = false; $q.notify({ type: 'positive', message: 'Payment proof submitted for verification.', position: 'top' }); await loadPayments() } catch (reason) { $q.notify({ type: 'negative', message: reason instanceof Error ? reason.message : 'Unable to submit payment.', position: 'top' }) } finally { submitting.value = false; proofFile.value = null } }
onMounted(() => { void loadPayments() })
</script>

<style scoped>
.payments-page { min-height: 100%; background: var(--m-bg); color: var(--m-text); }.payments-shell { width: 100%; max-width: 720px; margin: 0 auto; padding: max(var(--m-space-3), env(safe-area-inset-top)) var(--m-page-gutter) max(112px, calc(var(--m-space-8) + env(safe-area-inset-bottom))); }.payment-section { display: grid; gap: 10px; margin-bottom: 24px; }.section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }.section-heading h2,.lease-details h2,.state-panel h2,.sheet-heading h2 { margin: 0; color: var(--m-ink); font-size: 18px; font-weight: 800; line-height: 1.25; }.section-heading p,.state-panel p,.sheet-heading p { margin: 3px 0 0; color: var(--m-muted); font-size: 12px; line-height: 1.4; }.section-heading > span { min-width: 24px; padding: 3px 7px; border-radius: 999px; background: var(--m-bg); color: var(--m-muted); font-size: 11px; font-weight: 800; text-align: center; }.surface { overflow: hidden; border: 1px solid var(--m-border); border-radius: 12px; background: var(--m-surface); }.action-card { display: grid; grid-template-columns: 40px minmax(0,1fr) auto; align-items: center; gap: 12px; padding: 14px; }.action-card--overdue { border-color: #fecaca; background: var(--m-danger-soft); }.action-icon,.payment-icon,.state-icon { display: grid; width: 40px; height: 40px; place-items: center; border-radius: 10px; background: var(--m-warning-soft); color: var(--m-warning); }.action-card--overdue .action-icon { background: #fff; color: var(--m-danger); }.action-card div { display: grid; gap: 2px; }.action-card strong { color: var(--m-ink); font-size: 18px; font-weight: 800; }.action-card span,.action-card small { color: var(--m-muted); font-size: 11px; }.action-card small { color: var(--m-text); }.action-card button,.primary-action { min-height: 40px; padding: 0 12px; border: 0; border-radius: 8px; background: var(--m-primary-dark); color: #fff; font-size: 12px; font-weight: 800; }.action-card--overdue button { background: var(--m-danger); }.payment-row { display: grid; min-height: 76px; grid-template-columns: 40px minmax(0,1fr) auto; align-items: center; gap: 12px; padding: 12px; border-bottom: 1px solid var(--m-border); }.payment-row:last-child { border-bottom: 0; }.payment-icon--success { background: var(--m-success-soft); color: var(--m-success); }.payment-icon--danger { background: var(--m-danger-soft); color: var(--m-danger); }.payment-icon--neutral,.state-icon { background: var(--m-bg); color: var(--m-text); }.payment-copy { display: grid; min-width: 0; gap: 2px; }.payment-copy strong { color: var(--m-ink); font-size: 14px; font-weight: 800; }.payment-copy span,.payment-copy small { overflow: hidden; color: var(--m-muted); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }.history-side { display: grid; justify-items: end; gap: 4px; }.history-side a { color: var(--m-primary-dark); font-size: 10px; font-weight: 800; }.status-badge { min-height: 23px; padding: 4px 7px; border-radius: 999px; font-size: 10px; font-weight: 800; white-space: nowrap; }.status-badge--success { background: var(--m-success-soft); color: var(--m-success); }.status-badge--warning { background: var(--m-warning-soft); color: var(--m-warning); }.status-badge--danger { background: var(--m-danger-soft); color: var(--m-danger); }.status-badge--neutral { background: var(--m-bg); color: var(--m-text); }.empty-history { display: flex; min-height: 108px; flex-direction: column; align-items: center; justify-content: center; gap: 7px; color: var(--m-muted); }.empty-history p { margin: 0; font-size: 12px; }.lease-details { margin-top: 4px; }.lease-details h2 { padding: 14px; border-bottom: 1px solid var(--m-border); font-size: 16px; }.lease-details > div { display: flex; justify-content: space-between; gap: 16px; padding: 12px 14px; border-bottom: 1px solid var(--m-border); }.lease-details > div:last-child { border-bottom: 0; }.lease-details span { color: var(--m-muted); font-size: 12px; }.lease-details strong { max-width: 60%; color: var(--m-ink); font-size: 12px; text-align: right; }.state-panel { display: flex; min-height: 280px; flex-direction: column; align-items: flex-start; justify-content: center; padding: 24px; }.state-icon { margin-bottom: 16px; }.state-panel--error .state-icon { background: var(--m-danger-soft); color: var(--m-danger); }.state-panel p { margin: 8px 0 20px; font-size: 13px; line-height: 1.5; }.primary-action svg { margin-right: 7px; vertical-align: -3px; }.sheet-card { width: 100%; max-width: 720px; margin: 0 auto; border-radius: 16px 16px 0 0; }.sheet-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }.selected-file { margin: 10px 0 0; color: var(--m-primary-dark); font-size: 12px; font-weight: 750; }.file-hint { margin: 4px 0 0; color: var(--m-muted); font-size: 11px; }.loading-panel { padding: 12px; }.skeleton { height: 68px; margin-bottom: 12px; border-radius: 8px; background: #edf0f2; animation: pulse 1.4s ease infinite; }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; } @keyframes pulse { 50% { opacity: .48; } } @media (max-width:390px) { .action-card { grid-template-columns: 40px minmax(0,1fr); }.action-card button { grid-column: 2; justify-self: start; }.payment-row { grid-template-columns: 40px minmax(0,1fr); }.payment-row > .status-badge,.history-side { grid-column: 2; justify-self: start; } }
</style>
